insert into public.ciudades (nombre, moneda) values ('Tarija', 'BOB');

insert into public.zonas (ciudad_id, nombre)
select c.id, z.nombre from public.ciudades c, (values ('Centro'), ('Las Panosas'), ('San Roque'), ('El Molino'), ('La Pampa'), ('Villa Fátima'), ('San Jorge'), ('El Tejar')) as z (nombre)
where c.nombre = 'Tarija';

