alter table public.resenas enable trigger resenas_verificar;

-- Actividad de los últimos 30 días para las estadísticas del panel
insert into public.eventos (tipo, plato_id, restaurante_id, zona_id, creado_en)
select case when random() < 0.18 then 'como_llegar' else 'vista_plato' end, p.id, p.restaurante_id, r.zona_id,
  now() - (random() * interval '30 days')
from public.platos p
join public.restaurantes r on r.id = p.restaurante_id
cross join lateral generate_series(1, case when p.categoria_id = (select id from public.categorias where slug = 'hamburguesas') then 25 + (random() * 40)::int else 5 + (random() * 15)::int end) g;

insert into public.eventos (tipo, termino, zona_id, creado_en)
select 'busqueda', t.termino, z.id, now() - (random() * interval '30 days')
from (values ('hamburguesa', 60), ('smash', 18), ('pizza', 25), ('saice', 15), ('salteña', 22), ('pollo', 20), ('alitas', 10), ('sushi', 8), ('algo dulce', 12), ('lomito', 9)) as t (termino, veces)
cross join lateral generate_series(1, t.veces) g
cross join lateral (select id from public.zonas order by random() + g * 0 limit 1) z;

